`iec-st\nFUNCTION_BLOCK FB_PAN_Precursor_Spinning_Control
VAR_INPUT
    rDope_Extrusion_Pressure : REAL; (* Bar *)
    rCoagulation_Bath_Temp_PV : REAL; (* Deg C *)
    rCoagulation_Bath_Conc_PV : REAL; (* DMSO % *)
    rDraw_Roller_1_Speed_PV : REAL; (* m/min *)
    rDraw_Roller_2_Speed_PV : REAL; (* m/min *)
    rWashing_Zone_1_Temp_PV : REAL; (* Deg C *)
    rWashing_Zone_2_Temp_PV : REAL; (* Deg C *)
    rDrying_Oven_Temp_PV : REAL; (* Deg C *)

    bSystem_Enable : BOOL;
    bEmergency_Stop : BOOL;
    bBath_Circulation_Pump_Run : BOOL;
END_VAR

VAR_OUTPUT
    rDope_Pump_Speed_SP : REAL; (* RPM *)
    rCoagulation_Bath_Heater_CV : REAL; (* 0-100% *)
    rCoagulation_Bath_Solvent_Valve_CV : REAL; (* 0-100% *)
    rDraw_Roller_1_Speed_SP : REAL; (* m/min *)
    rDraw_Roller_2_Speed_SP : REAL; (* m/min *)
    rWashing_Heater_1_CV : REAL; (* 0-100% *)
    rWashing_Heater_2_CV : REAL; (* 0-100% *)
    rDrying_Oven_Heater_CV : REAL; (* 0-100% *)

    bSystem_Ready : BOOL;
    bAlarm_Pressure_High : BOOL;
    bAlarm_Stretch_Ratio_Mismatch : BOOL;
END_VAR

VAR
    rExtrusion_Pressure_SP : REAL := 15.5;
    rCoagulation_Bath_Temp_SP : REAL := 45.0;
    rCoagulation_Bath_Conc_SP : REAL := 60.0;
    rTarget_Stretch_Ratio : REAL := 4.5;
    rWashing_Zone_1_Temp_SP : REAL := 70.0;
    rWashing_Zone_2_Temp_SP : REAL := 85.0;
    rDrying_Oven_Temp_SP : REAL := 120.0;

    pidBathTemp : FB_PID_Controller;
    pidBathConc : FB_PID_Controller;
    pidExtrusionPress : FB_PID_Controller;
    pidWash1 : FB_PID_Controller;
    pidWash2 : FB_PID_Controller;
    pidDrying : FB_PID_Controller;

    rCurrent_Stretch_Ratio : REAL;
    tDelayTimer : TON;
END_VAR

(* Implementation *)
IF bEmergency_Stop OR NOT bSystem_Enable THEN
    rDope_Pump_Speed_SP := 0.0;
    rCoagulation_Bath_Heater_CV := 0.0;
    rCoagulation_Bath_Solvent_Valve_CV := 0.0;
    rDraw_Roller_1_Speed_SP := 0.0;
    rDraw_Roller_2_Speed_SP := 0.0;
    rWashing_Heater_1_CV := 0.0;
    rWashing_Heater_2_CV := 0.0;
    rDrying_Oven_Heater_CV := 0.0;
    bSystem_Ready := FALSE;
    RETURN;
END_IF;

bSystem_Ready := bBath_Circulation_Pump_Run;

(* 1. Dope Extrusion Pressure Control *)
pidExtrusionPress(
    rProcessValue := rDope_Extrusion_Pressure,
    rSetpoint := rExtrusion_Pressure_SP,
    rKp := 2.5, rKi := 1.1, rKd := 0.5,
    rControlValue => rDope_Pump_Speed_SP
);
IF rDope_Extrusion_Pressure > 20.0 THEN
    bAlarm_Pressure_High := TRUE;
ELSE
    bAlarm_Pressure_High := FALSE;
END_IF;

(* 2. Coagulation Bath Temperature and Concentration *)
pidBathTemp(
    rProcessValue := rCoagulation_Bath_Temp_PV,
    rSetpoint := rCoagulation_Bath_Temp_SP,
    rKp := 1.8, rKi := 0.2, rKd := 0.1,
    rControlValue => rCoagulation_Bath_Heater_CV
);

pidBathConc(
    rProcessValue := rCoagulation_Bath_Conc_PV,
    rSetpoint := rCoagulation_Bath_Conc_SP,
    rKp := 3.0, rKi := 0.5, rKd := 0.0,
    rControlValue => rCoagulation_Bath_Solvent_Valve_CV
);

(* 3. Draw Roller Stretch Ratio Kinematics *)
rDraw_Roller_1_Speed_SP := 10.0; (* Base speed m/min *)
rDraw_Roller_2_Speed_SP := rDraw_Roller_1_Speed_SP * rTarget_Stretch_Ratio;

IF rDraw_Roller_1_Speed_PV > 0.5 THEN
    rCurrent_Stretch_Ratio := rDraw_Roller_2_Speed_PV / rDraw_Roller_1_Speed_PV;
ELSE
    rCurrent_Stretch_Ratio := 0.0;
END_IF;

IF ABS(rCurrent_Stretch_Ratio - rTarget_Stretch_Ratio) > 0.2 AND rDraw_Roller_1_Speed_PV > 5.0 THEN
    tDelayTimer(IN := TRUE, PT := T#5S);
    IF tDelayTimer.Q THEN
        bAlarm_Stretch_Ratio_Mismatch := TRUE;
    END_IF;
ELSE
    tDelayTimer(IN := FALSE);
    bAlarm_Stretch_Ratio_Mismatch := FALSE;
END_IF;

(* 4. Washing and Drying Temperature Cascades *)
pidWash1(
    rProcessValue := rWashing_Zone_1_Temp_PV,
    rSetpoint := rWashing_Zone_1_Temp_SP,
    rKp := 1.5, rKi := 0.3, rKd := 0.0,
    rControlValue => rWashing_Heater_1_CV
);

pidWash2(
    rProcessValue := rWashing_Zone_2_Temp_PV,
    rSetpoint := rWashing_Zone_2_Temp_SP,
    rKp := 1.5, rKi := 0.3, rKd := 0.0,
    rControlValue => rWashing_Heater_2_CV
);

pidDrying(
    rProcessValue := rDrying_Oven_Temp_PV,
    rSetpoint := rDrying_Oven_Temp_SP,
    rKp := 2.0, rKi := 0.4, rKd := 0.1,
    rControlValue => rDrying_Oven_Heater_CV
);

END_FUNCTION_BLOCK
\n`
